// Docs screenshots of the delight layer, from the demo day (demo.html: fictional, no server) with the browser clock
// paused so they come out the same each time. Regenerated by `npm run screenshots` along with the others.
import { fileURLToPath } from 'node:url';
import { expect, type Page, test } from '@playwright/test';
import { noServer, person } from './helpers';

const out = (name: string) => fileURLToPath(new URL(`../../docs/screenshots/${name}`, import.meta.url));
const T0 = new Date('2026-10-13T12:00:00.000Z');

async function openDemoDay(page: Page, at: string) {
  await noServer(page);
  await page.clock.install({ time: T0 });
  await page.clock.pauseAt(new Date(T0.getTime() + 1000));
  await page.goto(`/demo.html?at=${at}&speed=60`);
  await page.clock.runFor(500);
  await expect(page.locator('[data-person]')).toHaveCount(23);
  await page.waitForTimeout(1600); // let the walk-ins and the chip layout settle
}

/** Zoom the camera in on something on the map (the wheel keeps the point under the mouse still), then move the mouse away. */
async function zoomOn(page: Page, selector: string, steps: number, dy = 0) {
  const box = await page.locator(selector).first().boundingBox();
  if (!box) throw new Error(`${selector} is not on the map`);
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2 + dy);
  for (let i = 0; i < steps; i += 1) {
    await page.mouse.wheel(0, -240);
    await page.waitForTimeout(60);
  }
  await page.mouse.move(1300, 860); // no hover ring in the shot
  await page.waitForTimeout(500);
}

/** Drag the map slowly (a fast drag would be parkour). */
async function pan(page: Page, dx: number, dy: number) {
  await page.mouse.move(900, 450);
  await page.mouse.down();
  for (let i = 1; i <= 12; i += 1) {
    await page.mouse.move(900 + (dx * i) / 12, 450 + (dy * i) / 12);
    await page.waitForTimeout(40);
  }
  await page.mouse.up();
  await page.mouse.move(1300, 860);
}

test.describe('@screenshot delight layer screenshots', () => {
  test('the Dundies ceremony', async ({ page }) => {
    await openDemoDay(page, '16:50');
    await page.keyboard.press('ControlOrMeta+k');
    await page.getByRole('combobox', { name: 'Ask Pam' }).fill('dundies');
    await page.keyboard.press('Enter');
    const win = page.getByRole('dialog', { name: 'The Dundies' });
    await expect(win.locator('[data-dundie="dont-go-in"]')).toBeVisible();
    await page.waitForTimeout(2800); // the awards come in one by one
    await page.screenshot({ path: out('dundies.png') });
  });

  test('Kevin\'s chili spill', async ({ page }) => {
    await openDemoDay(page, '11:05');
    await zoomOn(page, '[data-chili]', 4, -30);
    await pan(page, 180, -260);
    await page.waitForTimeout(1500); // the spill plays once
    await page.screenshot({ path: out('chili-spill.png') });
  });

  test('Creed\'s corner', async ({ page }) => {
    await openDemoDay(page, '11:05');
    await zoomOn(page, '[data-person="creed"]', 2);
    await person(page, /^Creed Bratton — /).click();
    await page.mouse.move(1300, 860);
    await expect(page.getByRole('dialog', { name: 'Creed’s corner' }).locator('[data-unattributed]')).toHaveCount(3);
    await page.screenshot({ path: out('creeds-corner.png') });
  });
});
